'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={capital:'Góp vốn',purchase:'Nhập nguyên liệu',sale:'Bán món',pay:'Trả nhà cung cấp',collect:'Thu nợ khách hàng',expense:'Ghi chi phí',asset:'Mua tài sản',depreciate:'Khấu hao tài sản',reserve:'Mục tiêu dự phòng',reverse_expense:'Đảo chi phí công nợ',close_period:'Khóa kỳ kế toán'};
let replay,step=0,report,view='overview',token='',live=false,branch='q1',pendingKey=null,pendingPayload=null;
const currency=v=>new Intl.NumberFormat(I18n.locale,{style:'currency',currency:report?.currency||'GBP',maximumFractionDigits:report?.minor_digits??2}).format(v/(10**(report?.minor_digits??2)));
const moneyRow=(label,value,cls='')=>`<div class="money-row ${cls}"><span>${label}</span><b>${currency(value)}</b></div>`;
function status(message,error=false){$('#status').textContent=message;$('#status').classList.toggle('error',error)}
function apiHeaders(){return {'Authorization':'Bearer '+token,'Content-Type':'application/json'}}
async function getReport(){const response=await fetch('/api/erp/report?branch='+encodeURIComponent(branch),{headers:apiHeaders(),cache:'no-store'});const body=await response.json();if(!response.ok)throw Error(body.detail||'Không tải được báo cáo');report=body}
function showReplay(){live=false;token='';$('#replay').hidden=false;$('#disconnectButton').hidden=true;$('#branchPicker').hidden=true;report=replay.steps[step].report;$('#stepSelect').value=String(step);$('#stepNumber').textContent=`${step+1} / ${replay.steps.length}`;$('#previousStep').disabled=step===0;$('#nextStep').disabled=step===replay.steps.length-1;$('#modeLabel').textContent='Xem quy trình mẫu · không ghi giao dịch online';$('#notice').textContent=replay.notice;render()}
function overview(){const p=report.pnl,l=report.liquidity;return `<div class="cards">${[['Doanh thu thuần',p.revenue_minor,'Không gồm thuế đầu ra'],['Lợi nhuận trước lãi vay, thuế',p.profit_before_interest_tax_minor,'Đã tính khấu hao'],['Tiền mặt + ngân hàng',l.cash_minor+l.bank_minor,'Số dư, không phải lợi nhuận'],['Sau mục tiêu dự phòng',l.liquidity_after_reserve_minor,'Chưa trừ nghĩa vụ chưa thanh toán']].map(([title,value,hint])=>`<div class="card"><span class="card-label">${title}</span><div class="big">${currency(value)}</div><small>${hint}</small></div>`).join('')}</div><div class="two"><div class="card"><div class="section-title"><h2>Từ doanh thu đến lợi nhuận</h2><span class="badge">${esc(report.currency)}</span></div>${moneyRow('Doanh thu thuần',p.revenue_minor)}${moneyRow('Giá vốn món đã bán',p.food_minor)}${moneyRow('Nhân sự',p.labor_minor)}${moneyRow('Thuê mặt bằng',p.rent_minor)}${moneyRow('Vận hành khác',p.other_minor)}${moneyRow('Lợi nhuận trước khấu hao',p.operating_profit_before_depreciation_minor)}${moneyRow('Khấu hao',p.depreciation_minor)}${moneyRow('Lợi nhuận trước lãi vay, thuế',p.profit_before_interest_tax_minor,'total')}<div class="help">Mua nguyên liệu chưa dùng nằm trong kho. Mua bàn ghế được ghi tài sản; khấu hao mới đi vào chi phí từng kỳ.</div></div><div class="card"><h2>Tiền và nghĩa vụ thanh toán</h2>${moneyRow('Tiền mặt',l.cash_minor)}${moneyRow('Ngân hàng',l.bank_minor)}${moneyRow('Phải thu khách hàng',accountBalance('1100'))}${moneyRow('Phải trả lương',report.liabilities_breakdown?.payroll_payable_minor||0)}${moneyRow('Phải trả khác',report.liabilities_breakdown?.other_payable_minor??-accountBalance('2000'))}${moneyRow('Mục tiêu giữ dự phòng',l.reserve_target_minor)}${moneyRow('Tiền sau mục tiêu dự phòng',l.liquidity_after_reserve_minor,'total')}<div class="help">Mục tiêu dự phòng không phải chi phí hay tiền đã chuyển sang một quỹ riêng. Con số còn lại chưa phải số tiền được phép phân phối: còn phải xem công nợ và nghĩa vụ khác.</div><h3 style="margin-top:22px">Cơ cấu chi phí</h3>${[['Nguyên liệu',p.food_minor],['Nhân sự',p.labor_minor],['Mặt bằng',p.rent_minor],['Khác',p.other_minor],['Khấu hao',p.depreciation_minor]].map(([name,value])=>{const total=p.food_minor+p.labor_minor+p.rent_minor+p.other_minor+p.depreciation_minor;return `<div class="money-row"><span>${name}</span><b>${total?Math.round(value/total*100):0}%</b></div><div class="bar"><i style="width:${total?Math.max(0,Math.min(100,value/total*100)):0}%"></i></div>`}).join('')}</div></div>`}
function accountBalance(code){const r=report.trial_balance.find(x=>x.account===code);return r?r.debit_balance_minor-r.credit_balance_minor:0}
function inventory(){return `<div class="two"><div class="card"><h2>Nguyên liệu còn trong kho</h2><p class="muted">Giá trị tồn theo nguyên giá mua; giá xuất dùng bình quân di động, tính theo đơn vị tiền nhỏ nhất.</p>${report.stock.length?report.stock.map(x=>`<div class="stock-card"><div class="stock-card-top"><b data-i18n-skip>${esc(x.name)}</b><span>${currency(x.value_minor)}</span></div><small>${x.quantity.toLocaleString(I18n.locale)} ${esc(x.unit)} còn lại</small></div>`).join(''):'<div class="empty">Chưa nhập nguyên liệu.</div>'}<div class="help">Khi bán món, nguyên liệu tự trừ theo định lượng. Thiếu một nguyên liệu sẽ từ chối toàn bộ đơn, không ghi doanh thu hoặc trừ kho dở dang.</div></div><div class="card"><h2>Định lượng minh họa</h2><p class="muted">Danh mục mẫu hiện có một món và hai nguyên liệu; quản trị danh mục tùy chỉnh cần phát triển tiếp.</p><h3>Cơm gà · giá thuần ${currency(1200)}</h3><div class="money-row"><span>Gạo / phần</span><b>100 g</b></div><div class="money-row"><span>Thịt gà / phần</span><b>150 g</b></div><div class="help">Mua hàng tạo kho và công nợ. Thanh toán nhà cung cấp giảm công nợ và tiền; không cộng giá vốn lần thứ hai.</div></div></div>`}
function assets(){return `<div class="two"><div class="card"><h2>Tái đầu tư & tài sản</h2>${report.assets.length?report.assets.map(x=>`<div class="asset-detail"><b data-i18n-skip>${esc(x.name)}</b><p>Ngày mua ${esc(I18n.date(x.business_date))} · ${x.life_months} tháng khấu hao</p>${moneyRow('Nguyên giá',x.cost_minor)}${moneyRow('Đã khấu hao',x.depreciated_minor)}${moneyRow('Giá trị còn lại',x.net_book_minor)}<small>ID: ${esc(x.id)}</small></div>`).join(''):'<div class="empty">Chưa ghi nhận tài sản.</div>'}<div class="help">MVP tính khấu hao đường thẳng theo tháng mua, không giá trị thu hồi; đây là giả định quản trị, chưa phải chính sách kế toán/thuế của từng nước.</div></div><div class="card"><h2>Dự phòng tiền mặt</h2>${moneyRow('Tiền mặt và ngân hàng',report.liquidity.cash_minor+report.liquidity.bank_minor)}${moneyRow('Mục tiêu dự phòng',report.liquidity.reserve_target_minor)}${moneyRow('Tiền sau mục tiêu',report.liquidity.liquidity_after_reserve_minor,'total')}<p class="muted">Tách tiền dự phòng ra khỏi lợi nhuận giúp tránh hiểu nhầm quán có lãi là có thể chi hết số tiền đó.</p><div class="help">Chưa xử lý dự phòng kế toán cho các nghĩa vụ ước tính. Đây chỉ là mục tiêu thanh khoản do chủ quán đặt.</div></div></div>`}
function ledger(){return `${report.integrity?.verified?'<div class="help" style="margin-bottom:18px"><b>Đã kiểm tra toàn vẹn dữ liệu</b><br>Chữ ký giao dịch, cân đối sổ, tồn kho và khóa kỳ đã được đối soát khi tạo báo cáo. Bản replay chỉ phản ánh lần kiểm tra dữ liệu mẫu.</div>':''}<div class="card"><div class="section-title"><h2>Bảng cân đối số dư tài khoản</h2><span class="badge">${report.balanced?'Nợ = Có':'Cần kiểm tra'}</span></div><div class="table-wrap"><table><thead><tr><th>Tài khoản quản trị</th><th>Dư Nợ</th><th>Dư Có</th></tr></thead><tbody>${report.trial_balance.filter(x=>x.debit_balance_minor||x.credit_balance_minor).map(x=>`<tr><td>${esc(x.account)} · ${esc(x.name)}</td><td>${currency(x.debit_balance_minor)}</td><td>${currency(x.credit_balance_minor)}</td></tr>`).join('')}<tr><td><b>Tổng cộng</b></td><td><b>${currency(report.trial_balance.reduce((sum,x)=>sum+x.debit_balance_minor,0))}</b></td><td><b>${currency(report.trial_balance.reduce((sum,x)=>sum+x.credit_balance_minor,0))}</b></td></tr></tbody></table></div><p class="muted">Hệ thống tài khoản quản trị mẫu; chưa ánh xạ báo cáo pháp định UK/EU. Cân bằng Nợ/Có không tự chứng minh chứng từ là đầy đủ hoặc hợp lệ.</p></div><div class="card" style="margin-top:20px"><h2>Truy vết từng chứng từ</h2>${documentList(true)}<h3>Kỳ đã khóa</h3><p class="muted">${report.closed_periods.length?report.closed_periods.map(x=>esc(x.month)+' · '+esc(x.closed_by)).join('<br>'):'Chưa khóa kỳ nào.'}</p></div>`}
function documentList(details=false){if(!report.documents.length)return '<div class="empty">Chưa có nghiệp vụ.</div>';return report.documents.slice().reverse().map(x=>`<details class="doc"><summary><span>${esc(labels[x.kind]||x.kind)}<small>${esc(I18n.date(x.business_date))} · ${esc(x.id.slice(0,8))}</small></span><span class="badge">${x.remaining_minor?'Còn nợ '+currency(x.remaining_minor):'Đã ghi nhận'}</span></summary><p>Người ghi nhận: ${esc(x.actor)} · ID ${esc(x.id)}</p>${x.lines.length?`<div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Nợ</th><th>Có</th></tr></thead><tbody>${x.lines.map(l=>`<tr><td>${esc(l.account)}</td><td>${currency(l.debit)}</td><td>${currency(l.credit)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nghiệp vụ quản lý, không tạo dòng Nợ/Có.</p>'}</details>`).join('')}
const input=(id,label,value='',type='number',extra='')=>`<div><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" '+(extra.includes('step=')?'':'step="'+(report.minor_digits===0?'1':'0.01')+'"'):''} ${extra} required></div>`;
const select=(id,label,items)=>`<div><label for="${id}">${label}</label><select id="${id}" required>${items.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('')}</select></div>`;
function transactions(){return `<div class="two"><div class="card"><h2>Ghi nghiệp vụ mới</h2><p class="muted">${live?'Giao dịch được ghi vào SQLite phía backend, có kiểm tra cân đối và quyền theo vai trò.':'Bạn đang xem quy trình mẫu. Muốn ghi nghiệp vụ thật, cần chạy backend Python và kết nối tài khoản trên máy chủ đó.'}</p><label for="operationType">Loại nghiệp vụ</label><select id="operationType">${Object.entries(labels).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select><form id="operationForm"><div class="form-grid" id="operationFields"></div><p id="operationHelp" class="muted"></p><button id="postButton" class="primary" ${live?'':'disabled'}>${live?'Kiểm tra & ghi sổ':'Cần backend để ghi nghiệp vụ'}</button></form></div><div class="card"><h2>Chứng từ đang có</h2>${documentList()}</div></div>`}
function renderFields(){const k=$('#operationType').value,credit=['bank','cash','credit'].map(v=>[v,{bank:'Ngân hàng',cash:'Tiền mặt',credit:k==='sale'?'Khách mua chịu':'Mua chịu / công nợ'}[v]]),cash=credit.slice(0,2);let fields=input('docDate','Ngày nghiệp vụ',new Date().toISOString().slice(0,10),'date');
 if(k==='capital')fields+=input('amount','Số tiền góp vốn ('+report.currency+')','5000')+select('payment','Nhận vào',cash);
 if(['purchase','expense','asset'].includes(k))fields+=input('net','Giá trị thuần ('+report.currency+')','100')+input('tax','Tiền thuế nhập thử ('+report.currency+')','0')+select('payment','Thanh toán',credit);
 if(k==='purchase')fields+=select('item','Nguyên liệu',[['rice','Gạo'],['chicken','Thịt gà']])+input('quantity','Số lượng (g)','1000','number','step="1"');
 if(k==='expense')fields+=select('category','Nhóm chi phí',[['rent','Thuê mặt bằng'],['labor','Nhân sự'],['other','Vận hành khác']]);
 if(k==='asset')fields+=input('assetName','Tên tài sản','Bàn ghế','text')+input('months','Thời gian khấu hao (tháng)','24','number','step="1"');
 if(k==='sale')fields+=select('product','Món bán',[['rice_chicken','Cơm gà · giá thuần '+currency(1200)]])+input('quantity','Số phần','1','number','step="1"')+input('tax','Tiền thuế cho cả đơn ('+report.currency+')','0')+select('payment','Khách thanh toán',credit);
 if(['pay','collect'].includes(k)){const invoices=report.documents.filter(x=>x.remaining_minor>0&&(k==='collect'?x.kind==='sale':['purchase','expense','asset'].includes(x.kind)));fields+=select('invoice','Chứng từ còn nợ',invoices.map(x=>[x.id,labels[x.kind]+' · '+x.id.slice(0,8)+' · '+currency(x.remaining_minor)]))+input('amount','Số thanh toán ('+report.currency+')','0')+select('payment','Tài khoản thanh toán',cash)}
 if(k==='depreciate')fields+=select('assetId','Tài sản',report.assets.filter(x=>x.net_book_minor>0).map(x=>[x.id,x.name+' · '+currency(x.net_book_minor)]));
 if(k==='reserve')fields+=input('target','Mục tiêu dự phòng ('+report.currency+')','200');
 if(k==='reverse_expense')fields+=select('expenseId','Chi phí công nợ chưa trả',report.documents.filter(x=>x.kind==='expense'&&x.remaining_minor>0).map(x=>[x.id,x.id.slice(0,8)+' · '+currency(x.remaining_minor)]));
 $('#operationFields').innerHTML=fields;$('#operationHelp').textContent=k==='close_period'?'Khóa tháng của ngày đã chọn cho chi nhánh hiện tại. MVP chưa có chức năng mở lại kỳ.':k==='sale'?'Bán món sẽ tự ghi doanh thu và giá vốn, trừ kho theo định lượng. Thiếu nguyên liệu sẽ từ chối toàn bộ đơn.':k==='depreciate'?'Khấu hao từng tháng liên tiếp từ tháng mua. Mỗi tài sản chỉ ghi một lần mỗi tháng.':'Số tiền thuế do bạn nhập chỉ dùng mô phỏng sổ; chưa có engine thuế UK/EU. Nghiệp vụ cần ghi theo thứ tự ngày.';
}
function minor(id){const text=$('#'+id).value.trim(),digits=report.minor_digits;const pattern=digits===0?/^\d+$/:/^\d+(?:[.,]\d{1,2})?$/;if(!pattern.test(text))throw Error('Nhập số tiền không có dấu phân cách hàng nghìn, tối đa '+digits+' chữ số thập phân');const [whole,fraction='']=text.replace(',','.').split('.');const value=Number(whole)*(10**digits)+Number(fraction.padEnd(digits,'0'));if(!Number.isSafeInteger(value))throw Error('Số tiền quá lớn');return value}
function formPayload(){const k=$('#operationType').value,p={kind:k,branch_id:branch,date:$('#docDate').value};if($('#payment'))p.payment=$('#payment').value;if(['capital','pay','collect'].includes(k))p.amount_minor=minor('amount');if(['purchase','expense','asset'].includes(k)){p.net_minor=minor('net');p.tax_minor=minor('tax')}if(['purchase','sale'].includes(k))p.quantity=Number($('#quantity').value);if(k==='purchase')p.item_id=$('#item').value;if(k==='expense')p.category=$('#category').value;if(k==='asset'){p.name=$('#assetName').value;p.life_months=Number($('#months').value)}if(k==='sale'){p.items=[{product_id:$('#product').value,quantity:p.quantity}];delete p.quantity;p.tax_minor=minor('tax')}if(['pay','collect'].includes(k))p.invoice_id=$('#invoice').value;if(k==='depreciate')p.asset_id=$('#assetId').value;if(k==='reserve')p.target_minor=minor('target');if(k==='reverse_expense')p.document_id=$('#expenseId').value;return p}
async function postForm(event){event.preventDefault();if(!live)return;const button=$('#postButton');button.disabled=true;let posted=false;try{const payload=formPayload(),serialized=JSON.stringify(payload);if(pendingPayload!==serialized){pendingKey=crypto.randomUUID();pendingPayload=serialized}const response=await fetch('/api/erp/documents',{method:'POST',headers:{...apiHeaders(),'Idempotency-Key':pendingKey},body:serialized});const result=await response.json();if(!response.ok)throw Error(result.detail||'Không ghi được nghiệp vụ');posted=true;await getReport();pendingKey=null;pendingPayload=null;render();status('Đã ghi nhận chứng từ '+result.document_id.slice(0,8)+'. Sổ và báo cáo đã được cập nhật.')}catch(error){status((posted?'Chứng từ đã ghi nhưng tải lại báo cáo gặp lỗi. Thử lại giữ cùng khóa để tránh ghi trùng. ':'')+error.message,true)}finally{if(button.isConnected)button.disabled=false}}
function render(){if(!report)return;$('#scope').textContent=`${{q1:'Bếp Trung Tâm',td:'Bếp Bờ Sông',dn:'Bếp Biển'}[report.branch_id]} · ${report.currency} · ${report.jurisdiction} · ${live?'Dữ liệu backend':'Dữ liệu mẫu'}`;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x.dataset.view===view);x.setAttribute('aria-current',x.dataset.view===view?'page':'false')});$('#content').innerHTML=({overview,transactions,inventory,assets,ledger})[view]();if(view==='transactions'){renderFields();$('#operationType').onchange=()=>{pendingKey=null;pendingPayload=null;renderFields()};$('#operationForm').onsubmit=postForm}}
document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{view=x.dataset.view;status('');render()});$('#stepSelect').onchange=e=>{step=+e.target.value;showReplay()};$('#previousStep').onclick=()=>{if(step>0){step--;showReplay()}};$('#nextStep').onclick=()=>{if(step<replay.steps.length-1){step++;showReplay()}};
$('#connectButton').onclick=()=>{$('#connectError').textContent='';$('#connectDialog').showModal()};$('#cancelConnect').onclick=()=>$('#connectDialog').close();$('#disconnectButton').onclick=()=>{showReplay();status('Đã ngắt kết nối trong tab. Dữ liệu backend vẫn được giữ.')};$('#opsBranch').onchange=async e=>{const old=branch;branch=e.target.value;try{await getReport();render()}catch(error){branch=old;e.target.value=old;status(error.message,true)}};
$('#connectForm').onsubmit=async e=>{e.preventDefault();const old=token;token=$('#accessToken').value;try{await getReport();live=true;$('#connectDialog').close();$('#accessToken').value='';$('#replay').hidden=true;$('#disconnectButton').hidden=false;$('#branchPicker').hidden=false;$('#modeLabel').textContent='Backend Python/SQL · đang kết nối';$('#notice').textContent='Nghiệp vụ sẽ ghi thật vào cơ sở dữ liệu của backend bạn đang dùng. Chưa cấu hình báo cáo/thuế pháp định.';render();status('Đã kết nối backend.')}catch(error){token=old;$('#connectError').textContent=error.message}};
$('#exportButton').onclick=()=>{if(!report)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({mode:live?'local_backend':'sample_replay',...report},null,2)],{type:'application/json'}));a.download='bep-erp-report-'+report.currency+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
(async()=>{try{const response=await fetch('demo.json',{cache:'no-store'});if(!response.ok)throw Error('Không tải được dữ liệu mẫu');replay=await response.json();$('#stepSelect').innerHTML=replay.steps.map((x,i)=>`<option value="${i}">${i+1}. ${esc(x.title)}</option>`).join('');showReplay();try{const response=await fetch('/api/erp/status',{cache:'no-store'});if(response.ok&&(await response.json()).engine==='bep-python-sql')$('#connectButton').disabled=false}catch{}}catch(error){status(error.message,true)}})();
window.addEventListener('bep:languagechange',()=>{
 if(!report)return;
 const operation=$('#operationType')?.value;
 const fields=[...document.querySelectorAll('#operationForm input,#operationForm select')].map(el=>({id:el.id,value:el.value}));
 const opened=[...document.querySelectorAll('details.doc')].map(el=>el.open);
 const focusId=document.activeElement?.id,scrollY=window.scrollY;
 render();
 if(operation&&$('#operationType')){$('#operationType').value=operation;renderFields();for(const field of fields){const el=document.getElementById(field.id);if(el)el.value=field.value}}
 document.querySelectorAll('details.doc').forEach((el,index)=>el.open=opened[index]||false);
 if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
 window.scrollTo({top:scrollY,behavior:'instant'});
});
